const audioCtx = new (window.AudioContext  window.webkitAudioContext)();

let gameStarted = false, score = 0, level = 1, diffMult = 1;
let mx = 500, my = 300, scopeX = 500, scopeY = 300; 
let shakeX = 0, shakeY = 0, recoilY = 0;
let windForce = 0, breath = 100, isHoldingBreath = false;

// Исправленные координаты: Земля на y=480.
let stickman = { x: -50, y: 480, dx: 0, dy: 0, isJumping: false, state: 'idle', frame: 0 };
let particles = [];
let bulletTraces = [];
let scenery = [];

const locations = [
    { name: "CITY", sky: "

", elements: 12, goal: 15 }
];

window.addEventListener('mousemove', (e) => {
    const rect = container.getBoundingClientRect();
    mx = e.clientX - rect.left; my = e.clientY -

;
});
window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') isHoldingBreath = true;
    if (e.key === 'Tab') { e.preventDefault(); adminPanel.style.display = adminPanel.style.display === 'flex' ? 'none' : 'flex'; }
});
window.addEventListener('keyup', (e) => { if (e.code === 'Space') isHoldingBreath = false; });

function playGunshot() {
    if(audioCtx.state === 'suspended') audioCtx.resume();
    const osc = audioCtx.createOscillator();
    const gainNode = audioCtx.createGain();
    const filter = audioCtx.createBiquadFilter();
    const bufferSize = audioCtx.sampleRate * 1; 
    const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const noise = audioCtx.createBufferSource();
    noise.buffer = buffer;
    filter.type = 'lowpass'; filter.frequency.value = 1000;
    noise.connect(filter); filter.connect(gainNode); gainNode.connect(audioCtx.destination);
    gainNode.gain.setValueAtTime(1, audioCtx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.5);
    noise.start(); noise.stop(audioCtx.currentTime + 0.5);
}

function startGame(multiplier) {
    diffMult = multiplier;
    document.getElementById('start-menu').style.display = 'none';
    gameStarted = true; score = 0; document.getElementById('score-val').innerText = score;
    changeLevel(1); requestAnimationFrame(gameLoop);
}

function changeLevel(lvlIndex) {
    level = lvlIndex; document.getElementById('lvl-val').innerText = level;
    let loc = locations[level-1];
    scenery = [];
    for(let i=0; i<loc.elements; i++) {
        // isForeground = true означает, что объект будет закрывать стикмена (УКРЫТИЕ)
        scenery.push({ 
            x: Math.random()*1000, 
            w: 40+Math.random()*80, 
            h: 70+Math.random()*250, 
            shade: Math.random(),
            isForeground: Math.random() > 0.6 
        });
    }
    respawnTarget();
}

function updateStatus(text, color) {
    statusHud.innerText = `STATUS: ${text}`; statusHud.style.color = color; statusHud.style.borderBottomColor = color;
}

function respawnTarget() {
    stickman.y = 480; stickman.state = 'idle'; stickman.isJumping = false;
    let baseSpeed = parseInt(document.getElementById('speedInput').value);
    stickman.dx = baseSpeed * diffMult * (Math.random() > 0.5 ? 1 : -1);
    stickman.x = stickman.dx > 0 ? -50 : 1050;
    windForce = Math.round((Math.random() - 0.5) * 40);
    let dir = windForce > 0 ? "➔" : "⬅️";
    document.getElementById('wind-hud').innerText = windForce === 0 ? "CALM" : `${Math.abs(windForce)} KM/H ${dir}`;
    document.getElementById('wind-hud').style.color = windForce === 0 ? "

");
