Конечно! Вот пример скрипта для ходьбы персонажа в Unity 2D:

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerMovement : MonoBehaviour
{
    public float speed = 5f; // Скорость движения персонажа

    private Rigidbody2D rb;
    private Vector2 movement;

    void Start()
    {
        rb = GetComponent<Rigidbody2D>();
    }

    void Update()
    {
        // Получаем ввод от игрока
        movement.x = Input.GetAxisRaw("Horizontal");
        movement.y = Input.GetAxisRaw("Vertical");
    }

    void FixedUpdate()
    {
        // Двигаем персонажа
        rb.MovePosition(rb.position + movement * speed * Time.fixedDeltaTime);
    }
}
```

Просто добавьте этот скрипт к объекту, представляющему вашего персонажа, в Unity. Он будет перемещать персонажа в зависимости от нажатия клавиш со стрелками или WASD на клавиатуре. Вы можете настроить скорость движения, изменив значение переменной `speed`.

